{
  "translations": [
    {
      "id": "tos_08",
      "text": "로봇 메모리 동기화 및 고정 완료."
    },
    {
      "id": "tos_09",
      "text": "이거 꽤 소름 돋네."
    },
    {
      "id": "tos_10",
      "text": "밑에서 어디 있었어?"
    },
    {
      "id": "tos_11",
      "text": "어젯밤에 너희 얘기하는 거 들었어."
    },
    {
      "id": "tos_12",
      "text": "내 탓은 아니잖아."
    },
    {
      "id": "tos_13",
      "text": "당연히 준비됐지. 넌 록스타잖아!"
    },
    {
      "id": "tos_14",
      "text": "상황이 어때, 발리?"
    },
    {
      "id": "tos_15",
      "text": "10분 정도 남았어요."
    }
  ]
}

